"use strict";function t(t=24){let n="";for(;n.length<t;)n+=Math.random().toString(16).slice(2);return n.slice(0,t)}exports.buildOptimisticTx=function(t,{clientToken:n,localId:e}={}){const o=t||{};return{...o,id:e,localId:e,clientToken:n,__local:!0,__pending:!0,createdAt:o.occurredAt||(new Date).toISOString()}},exports.newClientToken=function(){return`ct_${Date.now().toString(36)}_${t(24)}`},exports.newLocalId=function(){return`local_${t(24)}`};
